#!/bin/bash
# Nod relay on a fresh Ubuntu/Debian VPS (tested target: Hetzner, Ubuntu 22.04/24.04).
#   sudo bash setup.sh relay.example.com [site.example.com]
# Installs Node 22 and Caddy, runs the relay as user 'nod' on 127.0.0.1:8787,
# Caddy serves https://<relay domain> with an automatic certificate, firewall allows 22/80/443.
# With a second domain, Caddy also serves the Nod web page (and /.well-known/assetlinks.json) from
# /var/www/nod on https://<site domain>. Both domains need an A record pointing at this server
# (no domain? use <ip>.sslip.io, e.g. 203-0-113-7.sslip.io).
# Safe to run again: updates the relay and the site, keeps the registration key and the state, and
# remembers the site domain (so running it with only the relay domain does not remove the site).
set -euo pipefail
DOMAIN="${1:-}"
SITE_DOMAIN="${2:-}"
SITE_DIR=/var/www/nod
[ -n "$DOMAIN" ] || { echo "usage: sudo bash setup.sh relay.example.com [site.example.com]"; exit 1; }
[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
say() { echo; echo "==> $*"; }
# Remember the site domain from an earlier run when none is given now.
if [ -z "$SITE_DOMAIN" ] && [ -f /etc/nod/site-domain ]; then SITE_DOMAIN=$(cat /etc/nod/site-domain); fi
if [ -n "$SITE_DOMAIN" ] && [ "$SITE_DOMAIN" = "$DOMAIN" ]; then
  echo "The site and the relay need different domains (the relay answers on its own)."; exit 1
fi

say "Checking DNS"
MYIP=$(curl -4 -fsS https://api.ipify.org || true)
for NAME in "$DOMAIN" ${SITE_DOMAIN:+"$SITE_DOMAIN"}; do
  DNSIP=$(getent ahostsv4 "$NAME" | awk 'NR==1{print $1}' || true)
  echo "this server: ${MYIP:-unknown}   $NAME points to: ${DNSIP:-nothing}"
  if [ -n "$MYIP" ] && [ "$MYIP" != "$DNSIP" ]; then
    echo "WARNING: $NAME does not point at this server yet. Its HTTPS certificate will fail until it does."
    echo "Fix the A record, wait a few minutes, then run this script again."
  fi
done

say "Installing packages"
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq
apt-get install -y -qq curl ca-certificates gnupg ufw debian-keyring debian-archive-keyring apt-transport-https >/dev/null
if ! command -v node >/dev/null || [ "$(node -p 'process.versions.node.split(".")[0]')" -lt 20 ]; then
  curl -fsSL https://deb.nodesource.com/setup_22.x | bash - >/dev/null
  apt-get install -y -qq nodejs >/dev/null
fi
if ! command -v caddy >/dev/null; then
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -qq && apt-get install -y -qq caddy >/dev/null
fi
echo "node $(node -v), $(caddy version | cut -d' ' -f1)"

say "Installing the relay"
id nod >/dev/null 2>&1 || useradd --system --home /var/lib/nod --shell /usr/sbin/nologin nod
install -d -o nod -g nod -m 700 /var/lib/nod
install -d -m 755 /opt/nod-relay /etc/nod
echo "" | base64 -d | tar -xzf - -C /opt/nod-relay --strip-components=1
(cd /opt/nod-relay && npm install --omit=dev --no-audit --no-fund --silent)
if [ ! -f /etc/nod/relay.env ]; then
  KEY=$(head -c 48 /dev/urandom | base64 | tr -d '/+=' | cut -c1-40)
  printf 'RELAY_REGISTRATION_KEY=%s\n' "$KEY" > /etc/nod/relay.env
  chmod 600 /etc/nod/relay.env
fi

cat > /etc/systemd/system/nod-relay.service <<'UNIT'
[Unit]
Description=Nod relay
After=network-online.target
Wants=network-online.target

[Service]
User=nod
Group=nod
WorkingDirectory=/opt/nod-relay
EnvironmentFile=/etc/nod/relay.env
Environment=HOST=127.0.0.1 PORT=8787 RELAY_REQUIRE_HTTPS=1 RELAY_STATE_FILE=/var/lib/nod/relay-state.json NODE_ENV=production
ExecStart=/usr/bin/node /opt/nod-relay/server.js
Restart=always
RestartSec=2
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
ReadWritePaths=/var/lib/nod

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable --now nod-relay >/dev/null 2>&1
systemctl restart nod-relay

SITE_BLOCK=""
if [ -n "$SITE_DOMAIN" ]; then
  say "Installing the web page for $SITE_DOMAIN"
  install -d -m 755 "$SITE_DIR"
  # Replace the old page, but keep anything you added by hand (for example demo.mp4).
  find "$SITE_DIR" -mindepth 1 -maxdepth 1 \( -name index.html -o -name icon.png -o -name .well-known \) -exec rm -rf {} +
  echo "" | base64 -d | tar -xzf - -C "$SITE_DIR" --strip-components=1
  chmod -R a+rX "$SITE_DIR"
  printf '%s\n' "$SITE_DOMAIN" > /etc/nod/site-domain
  SITE_BLOCK="
$SITE_DOMAIN {
	root * $SITE_DIR
	encode gzip
	file_server
	header {
		X-Content-Type-Options nosniff
		Referrer-Policy no-referrer
	}
}"
fi

say "Configuring HTTPS"
cat > /etc/caddy/Caddyfile <<CADDY
$DOMAIN {
	reverse_proxy 127.0.0.1:8787
}
$SITE_BLOCK
CADDY
systemctl enable caddy >/dev/null 2>&1
systemctl reload caddy 2>/dev/null || systemctl restart caddy

say "Firewall: allowing only SSH, HTTP and HTTPS"
ufw allow 22/tcp >/dev/null; ufw allow 80/tcp >/dev/null; ufw allow 443/tcp >/dev/null
ufw --force enable >/dev/null

say "Checking"
sleep 3
systemctl is-active --quiet nod-relay && echo "relay: running" || { echo "relay: NOT running"; journalctl -u nod-relay -n 20 --no-pager; exit 1; }
for i in $(seq 1 20); do
  if curl -fsS "https://$DOMAIN/health" >/dev/null 2>&1; then echo "https://$DOMAIN/health: OK"; OK=1; break; fi
  sleep 3
done
[ "${OK:-}" = 1 ] || echo "HTTPS not answering yet (certificate may still be issuing). Check: journalctl -u caddy -n 30"
if [ -n "$SITE_DOMAIN" ]; then
  for i in $(seq 1 20); do
    if curl -fsS "https://$SITE_DOMAIN/.well-known/assetlinks.json" >/dev/null 2>&1; then echo "https://$SITE_DOMAIN: OK"; SITE_OK=1; break; fi
    sleep 3
  done
  [ "${SITE_OK:-}" = 1 ] || echo "The site is not answering yet (certificate may still be issuing). Check: journalctl -u caddy -n 30"
fi

echo
echo "==================================================================="
echo " Relay:            https://$DOMAIN"
[ -n "$SITE_DOMAIN" ] && echo " Web page:         https://$SITE_DOMAIN"
echo " Registration key: $(cut -d= -f2 /etc/nod/relay.env)"
echo " Keep the key private. Pair from your Mac with:"
echo "   RELAY_REGISTRATION_KEY=<key> npm run pair -- --relay https://$DOMAIN"
echo "==================================================================="
